1	// The task declaration contract (docs/PRINCIPLES.md) — the single
2	// source of truth for what a `tasks/<name>/task.json` must carry.
3	// Both the author-time `task-declaration-shape` check and the executor-side
4	// `validate-dispatch` validate against this one function, so the accepted shape
5	// can never drift between the two surfaces.
6	
7	import { ACCEPTED_FREQUENCIES, cadenceTermFor, cadenceOf, statesConditions, DUE_TERM } from './calendar.mjs';
8	import { MODEL_FAMILIES } from './model-map.mjs';
9	import { EXECUTING_LEASH_MS } from './queue/leases.mjs';
10	import { normalizePolicy } from './merge-policy.mjs';
11	import { validatePreconditions, preconditionSignals, preconditionNeedsItem, NONE } from './precondition-policy.mjs';
12	import { applyTaskDefaults } from './task-defaults.mjs';
13	
14	// A declared timeout is always a whole number of seconds, > 0.
15	const isPositiveInt = (n) => Number.isInteger(n) && n > 0;
16	
17	// A code-work command must stay inside its own task directory — no absolute
18	// path and no `..` traversal in the command string — the same containment the
19	// worker-file rule gives agent_instructions (docs/PRINCIPLES.md).
20	const escapesTaskDir = (cmd) => /(^|\s)\//.test(cmd) || cmd.includes('..');
21	
22	// Task execution is two similar, consecutive phases — deterministic CODE-WORK,
23	// then AGENTIC WORK — and the field names say so. Neither phase is named for
24	// the other: the code phase is not preparation for the agent, it is the first
25	// of two peers, and a task may declare only it.
26	//
27	// Two renames have reached these fields (2026-08-06 agent_preprocessing →
28	// prework, 2026-08-18 prework → code-work). Every legacy key maps straight to
29	// today's canonical name rather than to its immediate successor, so a declaration
30	// written for the oldest vocabulary normalizes in one pass, and a canonical name
31	// wins where both are present.
32	//
33	// Scaffolding, not a second vocabulary the contract keeps: `legacy-task-fields`
34	// reports a declaration still on an old spelling, and the acceptance ends one
35	// convergence window after that advisory ships (#1642). Not "once nobody declares
36	// them" — nothing here can count that.
37	// @legacy-tolerance advisory:legacy-task-fields retire:#1642
38	export const LEGACY_FIELDS = {
39	  agent_preprocessing: 'code_work',
40	  agent_preprocessing_timeout: 'code_work_timeout',
41	  prework: 'code_work',
42	  prework_timeout: 'code_work_timeout',
43	  after: 'schedule_after',
44	  // 2026-09-03: the secrets a task needs are the CODE-WORK phase's (that is the
45	  // only phase that runs Action-side, where a secret exists), and the name says so.
46	  required_secrets: 'code_work_required_secrets',
47	};
48	
49	// The defaults live in task-defaults.mjs — a module with no imports, so the
50	// dashboard's browser bundle can fill them the way the loader does.
51	export { DEFAULT_AUTOMERGE, DEFAULT_AGENT_MODEL } from './task-defaults.mjs';
52	
53	// WHO MINTS AN OCCURRENCE, and WHAT MUST HOLD once one exists (docs/PRINCIPLES.md).
54	// Two fields, one sentence: `trigger` says whether the scheduler asks
55	// this task at every tick, `preconditions` says what has to be true for the run to
56	// go ahead — judged identically at a tick and at a pick. A `request` task is asked
57	// by nobody and runs from an item somebody created: a marked issue, a wake, a chain
58	// link, a fan-out target.
59	export const TRIGGER_SCHEDULE = 'schedule';
60	export const TRIGGER_REQUEST = 'request';
61	export const TRIGGERS = Object.freeze([TRIGGER_SCHEDULE, TRIGGER_REQUEST]);
62	
63	// The cadence a task keeps, as the term it states — `null` where it states none.
64	export const taskCadence = (decl) => cadenceOf(decl?.preconditions);
65	export const isScheduledTask = (decl) => decl?.trigger === TRIGGER_SCHEDULE;
66	
67	// Return the declaration with canonical field names and the defaults filled in.
68	// Non-objects pass through untouched so validateTaskDeclaration still reports
69	// them. Loaders (discover, resolve-dispatch) normalize once; everything
70	// downstream sees only `code_work` and never an absent defaulted field.
71	export function normalizeTaskDeclaration(decl, terms = new Map()) {
72	  if (decl === null || typeof decl !== 'object' || Array.isArray(decl)) return decl;
73	  const out = { ...decl };
74	  // The editor's schema pointer, when a caller hands over a parsed task.json whole.
75	  delete out.$schema;
76	  for (const [legacy, canonical] of Object.entries(LEGACY_FIELDS)) {
77	    if (out[legacy] !== undefined) {
78	      if (out[canonical] === undefined) out[canonical] = out[legacy];
79	      delete out[legacy];
80	    }
81	  }
82	  // THE FREQUENCY DOOR (docs/PRINCIPLES.md). `frequency` is retired: a task's
83	  // cadence is one of its own preconditions, read off its run history. A declaration
84	  // still carrying the field reads exactly as it always did — the field becomes the
85	  // cadence term it always meant, first in the expression, and a `none` beside it
86	  // (the empty precondition it used to need) drops; `manual` meant no schedule and
87	  // adds no term. The field itself does not survive the door: nothing downstream
88	  // reads it.
89	  //
90	  // Scaffolding, not a second vocabulary: `legacy-task-fields` reports the field,
91	  // and the nightly update rewrites a member's own task files (the
92	  // `task-cadence-terms` record), so the acceptance ends one convergence window
93	  // after #1725 ships (#1732).
94	  // @legacy-tolerance advisory:legacy-task-fields retire:#1732
95	  if (out.frequency !== undefined) {
96	    const stated = Array.isArray(out.preconditions) ? out.preconditions.filter((e) => String(e).trim() !== NONE) : [];
97	    if (ACCEPTED_FREQUENCIES.includes(out.frequency)) {
98	      const term = cadenceTermFor(out.frequency);
99	      out.preconditions = term === null || stated.some((e) => String(e).trim() === term) ? stated : [term, ...stated];
100	    } else {
101	      // An illegal frequency is still reported, as the illegal condition it becomes.
102	      out.preconditions = [`${DUE_TERM}:${out.frequency}`, ...stated];
103	    }
104	    delete out.frequency;
105	  }
106	  // A declaration stating no conditions carries the empty expression from here on,
107	  // so every reader judges one array: at a pick it holds, at a tick it is never asked.
108	  if (out.preconditions === undefined) out.preconditions = [];
109	  // THE TRIGGER DOOR. A declaration written before the field existed is read the way
110	  // the schedule was read then — off the SHAPE of the expression: conditions the
111	  // scheduler can judge put the task on the schedule; no conditions, or one that
112	  // reads the item itself, keep it off. Derived, never defaulted: the answer that
113	  // declaration already gives, so nothing changes behaviour by passing through here.
114	  //
115	  // Scaffolding, not a second vocabulary: `legacy-task-fields` reports a declaration
116	  // stating no trigger, and the nightly update writes the derived value into a
117	  // member's own task files (the `task-cadence-terms` record), so the derivation ends
118	  // one convergence window after that advisory ships (#1789).
119	  // @legacy-tolerance advisory:legacy-task-fields retire:#1789
120	  if (out.trigger === undefined) {
121	    out.trigger = statesConditions(out.preconditions) && !preconditionNeedsItem(out.preconditions, terms)
122	      ? TRIGGER_SCHEDULE
123	      : TRIGGER_REQUEST;
124	  }
125	  // The retired outcome ceilings become the outcome/policy pair. An explicit
126	  // `automerge` beside a legacy spelling wins: a half-migrated declaration
127	  // keeps the narrower intent it states.
128	  if (LEGACY_OUTCOMES[out.expected_outcome] !== undefined) {
129	    if (out.automerge === undefined) out.automerge = LEGACY_OUTCOMES[out.expected_outcome];
130	    out.expected_outcome = 'fresh_pr';
131	  }
132	  if (LEGACY_CEILINGS[out.expected_outcome] !== undefined) out.expected_outcome = LEGACY_CEILINGS[out.expected_outcome];
133	  return applyTaskDefaults(out);
134	}
135	
136	// What a task's run does to PULL REQUESTS (docs/PRINCIPLES.md, decision
137	// PRINCIPLES.md) — the write ceiling and the target in one word, resolved once by the
138	// executor before code-work and handed to both phases:
139	//   no_code_changes                  — never opens one.
140	//   fresh_pr                         — one on a freshly minted branch; the task's
141	//                                      earlier pull requests are left as they are.
142	//   amend_existing_or_create_new_pr  — pushes onto the task's newest open pull
143	//                                      request while it has no conflicts with its
144	//                                      base; a fresh branch otherwise.
145	//   supersede_existing_pr            — a fresh branch, and once the run's own pull
146	//                                      request exists the task's earlier ones close
147	//                                      as superseded (a green, unlanded one on an
148	//                                      auto-merge repo is landed instead).
149	// A declared MAXIMUM, not a promise: "no change" is always legal, and what (if
150	// anything) the run may then MERGE is the separate `automerge` policy — 'nothing',
151	// 'anything', or a list of diff classes merge-policy.mjs evaluates the actual diff
152	// against.
153	export const OUTCOMES = ['no_code_changes', 'fresh_pr', 'amend_existing_or_create_new_pr', 'supersede_existing_pr'];
154	export const OUTCOME_NO_PR = 'no_code_changes';
155	
156	// Whether a (canonical) outcome lets the run open a pull request at all — the
157	// half of the contract `automerge` hangs off.
158	export const opensPullRequest = (outcome) => outcome !== OUTCOME_NO_PR;
159	
160	// The retired one-word ceilings, each carrying the policy it always meant, and
161	// normalizing at the door like the code-work renames above: `open-pr` is a fresh-pr
162	// task that merges nothing, `merged-pr` one authorized for anything. Accepted on
163	// the same terms as the renames above — one convergence window past the advisory,
164	// and no longer (#1642).
165	// @legacy-tolerance advisory:legacy-task-fields retire:#1642
166	export const LEGACY_OUTCOMES = { 'open-pr': 'nothing', 'merged-pr': 'anything' };
167	
168	// The retired two-word generation, each the word it became: `none` never opened a
169	// pull request, `pr` opened a fresh one and left the task's earlier ones alone.
170	// Same terms as the pair above (#1642).
171	// @legacy-tolerance advisory:legacy-task-fields retire:#1642
172	export const LEGACY_CEILINGS = { none: 'no_code_changes', pr: 'fresh_pr' };
173	
174	// Today's word for any spelling the door accepts, or null for one it does not.
175	export function canonicalOutcome(outcome) {
176	  if (LEGACY_OUTCOMES[outcome] !== undefined) return 'fresh_pr';
177	  if (LEGACY_CEILINGS[outcome] !== undefined) return LEGACY_CEILINGS[outcome];
178	  return OUTCOMES.includes(outcome) ? outcome : null;
179	}
180	
181	
182	// The retired scope vocabulary. It routed a slot dispatch to one of two labels, and
183	// its last reader went with the slot scheduler (#974): reach is now a property of
184	// which endpoint the hand-off calls (`invocation_endpoint`), so nothing anywhere
185	// asks a task what its scope is.
186	//
187	// The values stay so a declaration still carrying the field VALIDATES rather than
188	// failing — nothing converges a member's task files, so a member cannot be moved
189	// off it by a release; `task-declaration-shape` raises it as an advisory rename
190	// instead, and the field is dropped as each declaration is next edited.
191	// @deprecated Declares nothing. Name an `invocation_endpoint` if the task needed
192	//   reach an ordinary session in its repo does not have.
193	// @legacy-tolerance advisory:task-declaration-shape retire:#1642
194	export const SESSION_SCOPES = ['self', 'fleet'];
195	
196	// What must happen to a task's work item when a recovery path would re-execute it
197	// (docs/PRINCIPLES.md). `requeue` is the safe-side default for sweep-shaped
198	// work; `needs-human` is the at-most-once dial a one-shot side effect declares.
199	export const INTERRUPT_POLICIES = ['requeue', 'needs-human'];
200	
201	
202	// The signal-collector vocabulary (PRINCIPLES.md). A task collects only the union
203	// of what its due tasks declare. `fleet` is canon-only (consumers cannot declare
204	// it) — that restriction is enforced where signals are collected, not here; the
205	// shape check only asserts a declared name is a real collector.
206	export const SIGNAL_NAMES = [
207	  'commits', 'prs', 'issues', 'branches', 'release',
208	  'localPacks', 'sharedMount', 'conversationLogs', 'stamp', 'fleet', 'request',
209	];
210	
211	// `description` — what the task does, or why it exists, for the person reading the
212	// declaration or a roster of them: free prose, bounded so it stays a summary. It
213	// must not restate what the other fields already say (the cadence, the
214	// conditions, the policy, the files); the writing-tasks skill holds that rule,
215	// which no check can read.
216	export const DESCRIPTION_MAX_WORDS = 50;
217	export const wordCount = (text) => String(text).trim().split(/\s+/).filter(Boolean).length;
218	export function descriptionProblem(description) {
219	  if (typeof description !== 'string') return { what: `"description" is not a string`, fix: 'write one sentence or two saying what the task does or why it exists' };
220	  if (description.trim() === '') return { what: '"description" is empty', fix: 'say what the task does or why it exists, or drop the field' };
221	  const words = wordCount(description);
222	  if (words > DESCRIPTION_MAX_WORDS) return { what: `"description" runs to ${words} words`, fix: `keep it to ${DESCRIPTION_MAX_WORDS} words — a summary, not the README` };
223	  return null;
224	}
225	
226	// Validate one task declaration. Returns an array of `{ what, fix }` problems —
227	// empty means the declaration is well-formed. Pure: no I/O, no imports of the
228	// task itself; the caller supplies the already-loaded default export.
229	export function validateTaskDeclaration(raw, terms = new Map()) {
230	  const decl = normalizeTaskDeclaration(raw, terms);
231	  if (decl === null || typeof decl !== 'object' || Array.isArray(decl)) {
232	    return [{ what: 'task.json is not a declaration object', fix: 'write one JSON object: { "id", "description", "expected_outcome", … }' }];
233	  }
234	  const problems = [];
235	  const bad = (what, fix) => problems.push({ what, fix });
236	
237	  if (typeof decl.id !== 'string' || decl.id.trim() === '') {
238	    bad('the task has no string "id"', 'give the task an "id" matching its directory name');
239	  }
240	  // Optional at the door — nothing converges a member's task files — and judged
241	  // only when declared; the shape check asks for one where it is missing.
242	  if (decl.description !== undefined) {
243	    const problem = descriptionProblem(decl.description);
244	    if (problem) bad(problem.what, problem.fix);
245	  }
246	  // `precondition_signals` is retired with the function form it belonged to
247	  // (#1617). The union is DERIVED from the expression's terms, each of which
248	  // names what it reads, so the collector can never disagree with what the gate
249	  // actually consults — a declared list can, and that is the whole reason the
250	  // derived one replaced it.
251	  if (decl.precondition_signals !== undefined) {
252	    bad('"precondition_signals" is retired', 'drop it — the signal union is derived from the conditions, each of which names what it reads');
253	  }
254	  if (!MODEL_FAMILIES.includes(decl.agent_model)) {
255	    bad(`"agent_model" ${JSON.stringify(decl.agent_model)} is not a legal model family`, `set one of: ${MODEL_FAMILIES.join(', ')}`);
256	  }
257	  if (!OUTCOMES.includes(decl.expected_outcome)) {
258	    bad(`"expected_outcome" ${JSON.stringify(decl.expected_outcome)} is not a legal outcome ceiling`, `set one of: ${OUTCOMES.join(', ')}`);
259	  }
260	  // automerge — defaulted to `nothing` beside `pr` at the door (the legacy
261	  // ceilings arrive here already carrying theirs), and validated as a policy
262	  // SHAPE only: whether every named
263	  // rule resolves is the policy engine's question, answered where the diff is
264	  // judged, and it fails closed there — never at author time, where the rule set
265	  // depends on which packs are active.
266	  if (opensPullRequest(decl.expected_outcome)) {
267	    if (decl.automerge === undefined) {
268	      bad(`a "${decl.expected_outcome}" task declares no "automerge"`, 'say what may land unreviewed: "nothing", "anything", or a list of diff classes, e.g. ["comment-only-changes", "readme-changes"]');
269	    } else {
270	      const policy = normalizePolicy(decl.automerge);
271	      if (policy.kind === 'invalid') {
272	        bad(`"automerge" is not a legal policy: ${policy.reason}`, 'set "nothing", "anything", or a list of rule names, each optionally reject:-prefixed');
273	      }
274	    }
275	  } else if (decl.automerge !== undefined) {
276	    bad(`a "${OUTCOME_NO_PR}" task declares "automerge"`, 'drop it — a task that opens no pull request has nothing to merge; or set expected_outcome: "fresh_pr"');
277	  }
278	  // agent_instructions — REQUIRED for an agentic task (agent_model !== 'none'):
279	  // that's the worker file the agent reads, and it has no default. A `none` task
280	  // runs no agent, so the field is not applicable and is neither required nor
281	  // validated when present.
282	  if (decl.agent_model !== 'none' && (typeof decl.agent_instructions !== 'string' || decl.agent_instructions.trim() === '')) {
283	    bad('an agentic task (agent_model !== "none") declares no string "agent_instructions"', 'point "agent_instructions" at the worker file beside task.json (e.g. "task.md")');
284	  }
285	  // The trigger is always present by the time anything holds a declaration — stated,
286	  // or derived at the door — so what is validated is the value, not its presence.
287	  if (!TRIGGERS.includes(decl.trigger)) {
288	    bad(`"${decl.trigger}" is not a legal trigger`,
289	      `write one of: ${TRIGGERS.map((t) => `"${t}"`).join(', ')} — "${TRIGGER_SCHEDULE}" is asked by the scheduler at every tick, "${TRIGGER_REQUEST}" runs only from an item somebody creates`);
290	  }
291	
292	  // ONE MECHANISM (#1617). `preconditions` — a list of named conditions, all of
293	  // which must hold — is the only gate a task declares. The `precondition`
294	  // function it replaced is retired rather than tolerated: two forms meant every
295	  // reader, every check and the evaluator itself had to ask which one was the
296	  // gate, and a task-local term does everything the function did while staying
297	  // pure over its inputs and testable at a chosen instant.
298	  //
299	  // A term answers three ways, not two: holds, does not hold, and `{ error }` —
300	  // it COULD NOT ANSWER. The third is a run failure rather than a verdict (F27):
301	  // a decline is a decision about the world, and one taken on an API that would
302	  // not answer is a guess whose write-backs cannot land.
303	  if (decl.precondition !== undefined) {
304	    bad('the task declares a "precondition" function, which is retired', 'move the gate into "preconditions" — a built-in condition, or a term this task\'s preconditions.mjs exports');
305	  }
306	  // OPTIONAL (PRINCIPLES.md): a task may require nothing, and then every occurrence of
307	  // it runs. What is NOT read off this list is whether the scheduler asks the task —
308	  // `trigger` says that. A retired `frequency` arrives here already turned into its
309	  // cadence term by the door.
310	  if (decl.preconditions !== undefined) {
311	    for (const problem of validatePreconditions(decl.preconditions, terms)) bad(problem.what, problem.fix);
312	  }
313	
314	  /**
315	   * model_from_request — OPTIONAL, and reserved to the engine's own built-in task.
316	   * A task that declares it runs at the model the ITEM names (`Model:`, written by
317	   * the scheduler run from a write-gated label), falling back to `agent_model` when the item
318	   * names none. It is the only field that lets anything on an item define behaviour,
319	   * so it is fenced rather than waved through (docs/PRINCIPLES.md, "Requests"): the shape check accepts
320	   * only `true`, and discovery gives pack tasks no way to be the built-in one.
321	   */
322	  if (decl.model_from_request !== undefined && decl.model_from_request !== true) {
323	    bad(`"model_from_request" ${JSON.stringify(decl.model_from_request)} is not \`true\``,
324	      'drop the field — only the engine\'s built-in request task reads a model off its item, and every other task names its own agent_model');
325	  }
326	
327	  /**
328	   * session_scope — OPTIONAL, and READ BY NOTHING. Kept validated rather than
329	   * rejected outright so a lingering declaration still loads: nothing carries a
330	   * task-file change across the fleet, so a member cannot be migrated off the field
331	   * by a release, and rejecting it would stop that member's task running over a word
332	   * that no longer does anything.
333	   * @deprecated Declares nothing since #974. Drop it; if the task needed reach an
334	   *   ordinary session in its repo does not have, name an `invocation_endpoint`.
335	   */
336	  if (decl.session_scope !== undefined && !SESSION_SCOPES.includes(decl.session_scope)) {
337	    bad(`"session_scope" ${JSON.stringify(decl.session_scope)} is not a legal session scope`, `drop it — the field is read by nothing; name an "invocation_endpoint" if the task needs wider reach`);
338	  }
339	
340	  // Code-work (docs/PRINCIPLES.md) — OPTIONAL. The deterministic first phase
341	  // of task execution, a command the scheduler runs as a subprocess. When present
342	  // it must be a non-empty, task-local command AND carry a positive-integer
343	  // code_work_timeout — the hard kill that bounds the subprocess.
344	  if (decl.code_work !== undefined) {
345	    if (typeof decl.code_work !== 'string' || decl.code_work.trim() === '') {
346	      bad('"code_work" is present but not a non-empty string', 'set it to a command whose executable is a script beside task.json, e.g. "node prepare.mjs"');
347	    } else if (escapesTaskDir(decl.code_work)) {
348	      bad('"code_work" reaches outside the task directory (absolute path or "..")', 'reference a sibling script only, e.g. "node prepare.mjs"');
349	    }
350	    if (!isPositiveInt(decl.code_work_timeout)) {
351	      bad('"code_work" is set but "code_work_timeout" is not a positive integer', 'add "code_work_timeout": the seconds after which the subprocess is killed and the task fails');
352	    } else if (decl.code_work_timeout * 1000 >= EXECUTING_LEASH_MS) {
353	      // F17: a code-work legally allowed to outlive the executing leash is reclaimed
354	      // WHILE ALIVE, and the failure is not one duplicate run but a livelock —
355	      // every tenure reclaimed before it can finish, code-work re-executing each
356	      // cycle, the occurrence never converging. The leash is the engine's, so the
357	      // comparison is made where a declaration is judged.
358	      bad(`"code_work_timeout" (${decl.code_work_timeout}s) reaches the executor's ${EXECUTING_LEASH_MS / 60e3}-minute claim leash`,
359	        `bound code_work under ${EXECUTING_LEASH_MS / 60e3} minutes — a code_work that can outlive the leash is reclaimed while still running, and the item livelocks`);
360	    }
361	  }
362	
363	  // --- the work-item queue's three optional declarations (docs/PRINCIPLES.md) ---
364	
365	  // `schedule_after` — ordering, declared (PRINCIPLES.md). A list of `<pack>/<task>` ids this
366	  // task yields to WHILE THEY ARE LIVE THIS CYCLE. It compiles to the executor's
367	  // pick-time yield, never to a `Blocked-by` edge: a standing item that rolls
368	  // never closes, so blocked-by would starve every dependent of a quiet upstream
369	  // forever. The engine never learns what any named task does — it reads item
370	  // states, generically.
371	  if (decl.schedule_after !== undefined
372	      && !(Array.isArray(decl.schedule_after)
373	        && decl.schedule_after.every((s) => typeof s === 'string' && /^[^/\s]+\/[^/\s]+$/.test(s)))) {
374	    bad('"schedule_after" is not an array of "<pack>/<task>" ids', 'e.g. "schedule_after": ["claudinite-lifecycle/update"] — this task is not scheduled onto an executor while those are live this cycle');
375	  }
376	
377	  // `on_interrupt` — the ack-early/ack-late dial (PRINCIPLES.md). Most of this fleet's
378	  // tasks are sweep-shaped and converge safely on a re-run, so the default is
379	  // `requeue`. A genuinely one-shot side effect (a store submission, an external
380	  // notification) declares `needs-human`, and every recovery path that would
381	  // re-execute it — the leash reclaim, the hand-off retry — converges to triage
382	  // instead: at-most-once plus a human.
383	  if (decl.on_interrupt !== undefined && !INTERRUPT_POLICIES.includes(decl.on_interrupt)) {
384	    bad(`"on_interrupt" ${JSON.stringify(decl.on_interrupt)} is not a legal policy`, `set one of: ${INTERRUPT_POLICIES.join(', ')} (default "requeue")`);
385	  }
386	
387	  // `invocation_endpoint` — a NAME, never a URL (PRINCIPLES.md). The repo's config
388	  // maps the name to the URL and to the name of the Actions secret holding its
389	  // token, so no vendored pack file carries deployment detail or anything adjacent
390	  // to a credential. This is also what replaces session_scope: reach is a property
391	  // of which endpoint a task names.
392	  if (decl.invocation_endpoint !== undefined
393	      && !(typeof decl.invocation_endpoint === 'string' && /^[a-z0-9]+(-[a-z0-9]+)*$/.test(decl.invocation_endpoint))) {
394	    bad('"invocation_endpoint" is not a kebab-case endpoint name', 'name a key from the repo\'s taskScheduler.agenticTaskInvocationEndpoints map, e.g. "fleet" — never a URL');
395	  }
396	
397	  // The repo Actions secrets this task's code work needs configured (PRINCIPLES.md). Purely
398	  // DECLARATIVE — like a pack's adoption `questions`, its job is to drive the ask
399	  // (adoption interactively, the scheduler by owner issue), not to gate anything
400	  // here. So the only shape asserted is "a list of names"; whether the repo has
401	  // actually configured them is a fact about the repo, answered where the secrets
402	  // bundle is readable, never at author time.
403	  if (decl.code_work_required_secrets !== undefined
404	      && !(Array.isArray(decl.code_work_required_secrets) && decl.code_work_required_secrets.every((s) => typeof s === 'string' && s.trim() !== ''))) {
405	    bad('"code_work_required_secrets" is not an array of secret names', 'list the repo Actions secret names this task needs, e.g. ["SOME_API_KEY"]');
406	  }
407	
408	  // The one exception to "whether the repo has them is not our business": GitHub
409	  // reserves the `GITHUB_` prefix, answering "Secret names must not start with
410	  // GITHUB_" on the secret form. Such a name cannot be configured by anyone, so the
411	  // task parks forever on a secret its owner is refused — and only the declaration
412	  // can catch it, since the park reads as ordinary missing configuration.
413	  for (const name of (Array.isArray(decl.code_work_required_secrets) ? decl.code_work_required_secrets : [])) {
414	    if (typeof name === 'string' && name.toUpperCase().startsWith('GITHUB_')) {
415	      bad(`required secret "${name}" cannot be created — GitHub reserves the GITHUB_ prefix`,
416	        'rename it without that prefix, e.g. one carrying the pack\'s own name');
417	    }
418	    // The other namespace a secret cannot borrow. `CLAUDINITE_*` in a task file is the
419	    // code-work contract, and `task-code-work-env` reads every name outside that
420	    // contract as a variable nobody sets — which a delivered secret is not, so the
421	    // finding would be unfixable without renaming the secret anyway.
422	    if (typeof name === 'string' && name.toUpperCase().startsWith('CLAUDINITE_')) {
423	      bad(`required secret "${name}" sits in the code-work namespace, which its task's own code may not read`,
424	        'rename it outside CLAUDINITE_* — that prefix belongs to the variables code_work is handed');
425	    }
426	  }
427	
428	  // Execution bound (docs/PRINCIPLES.md) — an agentic task MUST
429	  // declare a positive-integer agent_execution_timeout: there is no default,
430	  // because a running agent always has a bound. Enforcement is best-effort (the
431	  // executor surfaces the value to the subagent). A `none` task runs no agent,
432	  // so it needs none.
433	  if (MODEL_FAMILIES.includes(decl.agent_model) && decl.agent_model !== 'none' && !isPositiveInt(decl.agent_execution_timeout)) {
434	    bad('an agentic task (agent_model !== "none") declares no positive-integer "agent_execution_timeout"', 'add "agent_execution_timeout": the seconds bounding the agentic run — generous; extreme protection, not a scheduling knob');
435	  }
436	
437	  // An agentless task (agent_model: none) runs no agent, so its ONLY work is
438	  // code-work — a `none` task with no code-work does nothing (PRINCIPLES.md, retiring
439	  // the in-process inline path). Require the command.
440	  if (decl.agent_model === 'none' && decl.code_work === undefined) {
441	    bad('an agentless task (agent_model: "none") declares no "code_work"', 'add "code_work" (a none task does its work in that subprocess) — or give the task an agent_model');
442	  }
443	
444	  return problems;
445	}
446	
447	// The signals to collect for one task, derived from the terms its conditions
448	// name. There is nothing to reconcile: a declared list could disagree with what
449	// the gate actually consults, and the derived union cannot.
450	export function taskSignalNames(decl, terms = new Map()) {
451	  return preconditionSignals(decl?.preconditions ?? [], terms);
452	}
453

