1	import { finding } from '../../../engine/checks/helpers/findings.mjs';
2	// Namespace-imported and guarded for the same reason legacy-shape-in-use is: a
3	// member's pack lane and engine lane converge on separate cycles, and this pack
4	// can sit beside a task-contract that predates either export.
5	import * as contract from '../task-contract.mjs';
6	import * as calendar from '../calendar.mjs';
7	import * as declarationText from '../task-declaration-text.mjs';
8	
9	// THE ADVISORY HALF OF THE TASK CONTRACT'S FIELD TOLERANCES. `normalizeTaskDeclaration`
10	// accepts two generations of field names, the retired one-word outcome ceilings,
11	// the retired `frequency` field (which reads as the cadence term it always meant,
12	// docs/PRINCIPLES.md) and a declaration stating no `trigger` (whose value is
13	// derived from the shape of its conditions), so a task declared in the oldest
14	// vocabulary runs exactly like one declared today — and nothing told its author that
15	// the acceptance ends a convergence window after this advisory ships (#1642, #1725).
16	//
17	// The trigger half is the odd one: what it reports is an ABSENCE, not a spelling, so
18	// there is no wrong line to point at — it points at the line the field goes ON, which
19	// is the anchor the nightly rewrite uses to put it there.
20	//
21	// It reads the declaration SOURCE rather than the normalized object, because by
22	// the time anything holds a task declaration the legacy spelling is gone: the
23	// door normalizes at load, which is what makes the tolerance invisible.
24	// Matching is therefore textual and deliberately conservative — a top-level key
25	// line in a task declaration — so the finding always points at a line an author
26	// can edit. The key is quoted and the value quote is whichever the file uses.
27	//
28	// ADVISORY: the old spelling works, and a task file is a member's own content.
29	const TASK_FILE = /(^|\/)tasks\/[^/]+\/task\.json$/;
30	const isTaskFile = (path) =>
31	  (typeof declarationText.isTaskDeclarationPath === 'function'
32	    ? declarationText.isTaskDeclarationPath(path)
33	    : TASK_FILE.test(path));
34	
35	const rule = {
36	  id: 'legacy-task-fields',
37	  severity: 'advisory',
