1	// The scheduling CALENDAR — the frequency vocabulary and the anchor arithmetic
2	// (docs/PRINCIPLES.md). Pure and stateless: given the repo's `schedule`
3	// anchor (dailyHour, weeklyDay, monthlyDay), a frequency and a `now`, it answers
4	// exactly one question — WHEN is that frequency's most recent occurrence at or
5	// before `now`.
6	//
7	// There is no occurrence IDENTITY here, and that is the point: under the
8	// work-item queue an occurrence is identified by the item's issue number, so the
9	// calendar owns the instants and nothing else. `queue/anchors.mjs` is the only
10	// consumer of the arithmetic; the vocabulary below is what the task contract and
11	// the author-time declaration check read.
12	//
13	// All times are UTC (the `schedule` values are UTC by contract). This module
14	// never reads the clock itself — `now` is always injected — so every answer is
15	// deterministic and testable.
16	
17	// The legal frequency tokens — the vocabulary the runtime contract validates
18	// against and the author-time declaration check rejects anything outside.
19	//
20	// `manual` is the one non-cadence: a manual task has no occurrence at all, so the
21	// scheduler run never instantiates it and it runs only from an item created by hand
22	// (`queue/create-work-item.mjs`). It exists for operator levers — work that
23	// answers no recurring question but wants a task's whole apparatus (declaration,
24	// contract validation, code-work, the work item) when a human pulls it.
25	export const FREQUENCIES = ['daily', 'weekly', 'monthly', 'manual'];
26	
27	// The documented anchor defaults (docs/PRINCIPLES.md) — applied
28	// when a repo omits `schedule` or any of its keys. This is the single source of
29	// these values; the checks layer's load-time range validation
30	// (engine/checks/helpers/repo-context.mjs) only bounds them, it does not
31	// re-declare them.
32	export const DEFAULT_SCHEDULE = { dailyHour: 4, weeklyDay: 'Sun', monthlyDay: 1 };
33	
34	// Sun-indexed to match Date#getUTCDay (0 = Sunday). Also the canonical weekday
35	// vocabulary the config validator mirrors.
36	export const WEEKDAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
37	
38	const HOUR_MS = 3600 * 1000;
39	const DAY_MS = 24 * HOUR_MS;
40	
41	// Last calendar day of a UTC month (day 0 of the next month rolls back).
42	const daysInMonth = (year, monthIndex) => new Date(Date.UTC(year, monthIndex + 1, 0)).getUTCDate();
43	
44	// Fill any absent key with its documented default; leave present values
45	// untouched (the checks layer has already range-validated them at load).
46	export function normalizeSchedule(schedule = {}) {
47	  const s = schedule || {};
48	  return {
49	    dailyHour: Number.isInteger(s.dailyHour) ? s.dailyHour : DEFAULT_SCHEDULE.dailyHour,
50	    weeklyDay: WEEKDAYS.includes(s.weeklyDay) ? s.weeklyDay : DEFAULT_SCHEDULE.weeklyDay,
51	    monthlyDay: Number.isInteger(s.monthlyDay) ? s.monthlyDay : DEFAULT_SCHEDULE.monthlyDay,
52	  };
53	}
54	
55	// The most recent occurrence of `frequency` at or before `now`, as a Date —
56	// `null` for `manual`, which has none. `now` may be a Date or anything the Date
57	// constructor accepts; `schedule` is normalized here, so callers need not.
58	export function anchorInstant(frequency, schedule, now) {
59	  const s = normalizeSchedule(schedule);
60	  const at = new Date(now);
61	  const nowMs = at.getTime();
62	  const freq = frequency;
63	
64	  if (freq === 'manual') return null;
65	
66	  if (freq === 'daily') {
67	    // Walk anchor DATES back from today until the instant is ≤ now: today's anchor hour may not
68	    // have come yet, in which case the most recent occurrence is yesterday's.
69	    let anchor = new Date(Date.UTC(at.getUTCFullYear(), at.getUTCMonth(), at.getUTCDate()));
70	    for (;;) {
71	      const time = new Date(anchor.getTime() + s.dailyHour * HOUR_MS);
72	      if (time.getTime() <= nowMs) return time;
73	      anchor = new Date(anchor.getTime() - DAY_MS);
74	    }
75	  }
76	
77	  if (freq === 'weekly') {
78	    const targetDow = WEEKDAYS.indexOf(s.weeklyDay);
79	    let date = new Date(Date.UTC(at.getUTCFullYear(), at.getUTCMonth(), at.getUTCDate()));
80	    // Up to 8 steps guarantees the previous week's occurrence even when today is
81	    // the weekly day but earlier than dailyHour.
82	    for (let i = 0; i < 8; i += 1) {
83	      if (date.getUTCDay() === targetDow) {
84	        const time = new Date(date.getTime() + s.dailyHour * HOUR_MS);
85	        if (time.getTime() <= nowMs) return time;
86	      }
87	      date = new Date(date.getTime() - DAY_MS);
88	    }
89	    // Unreachable in practice (a matching weekday always exists within 7 days).
90	    throw new Error(`no weekly occurrence resolved for ${s.weeklyDay}`);
91	  }
92	
93	  if (freq === 'monthly') {
94	    let year = at.getUTCFullYear();
95	    let month = at.getUTCMonth();
96	    for (;;) {
97	      const day = Math.min(s.monthlyDay, daysInMonth(year, month)); // clamp to month length (docs/PRINCIPLES.md)
98	      const time = new Date(Date.UTC(year, month, day) + s.dailyHour * HOUR_MS);
99	      if (time.getTime() <= nowMs) return time;
100	      month -= 1;
101	      if (month < 0) { month = 11; year -= 1; }
102	    }
103	  }
104	
105	  throw new Error(`unknown frequency "${frequency}"`);
106	}
107	
108	// --- the cadence terms ----------------------------------------------------------
109	// How a task states WHEN it runs, inside its own `preconditions`
110	// (docs/PRINCIPLES.md): the engine keeps no calendar of its own, so the cadence is one of the
111	// task's conditions, read off its own run history at every scheduler tick.
112	//
113	//   due:<daily|weekly|monthly>   no run since that cadence's most recent anchor on
114	//                                this repo's schedule — fixed hours, no drift
115	//   last-run-over:<12h|1d|7d>    the newest run started more than that long ago
116	//
117	// Whether a task is asked at all is its `trigger`, not the shape of this list: a
118	// task nothing asks may still state conditions, which are judged when somebody
119	// creates an item for it (the retired `frequency: manual` is `trigger: 'request'`).
120	//
121	// The parse lives here, beside the frequency vocabulary it replaces, and imports
122	// nothing: the dashboard's browser bundle reads a cadence the way the scheduler does.
123	export const CADENCES = ['daily', 'weekly', 'monthly'];
124	export const DUE_TERM = 'due';
125	export const ELAPSED_TERM = 'last-run-over';
126	export const NOT_FAILED_TERM = 'last-run-not-failed';
127	
128	// `12h`, `1d`, `7d` — a whole number of hours or days, nothing else.
129	const DURATION_RE = /^(\d+)(h|d)$/;
130	export function parseDuration(text) {
131	  const m = DURATION_RE.exec(String(text ?? ''));
132	  if (!m) return null;
133	  const n = Number(m[1]);
134	  return n > 0 ? n * (m[2] === 'h' ? HOUR_MS : DAY_MS) : null;
135	}
136	
137	// The term references an expression carries: each entry split on `||`, each
138	// reference `{ name, arg }` with the argument after the first colon. The same
139	// grammar precondition-policy.mjs parses, re-spelled here so this module stays
140	// import-free; the policy engine's parse is the one that validates.
141	const alternativesOf = (entry) => String(entry ?? '').split('||').map((t) => t.trim()).filter(Boolean)
142	  .map((t) => { const c = t.indexOf(':'); return c === -1 ? { name: t, arg: null } : { name: t.slice(0, c).trim(), arg: t.slice(c + 1).trim() }; });
143	const entriesOf = (preconditions) => (Array.isArray(preconditions) ? preconditions : []).map(alternativesOf);
144	
145	// The cadence a declaration states — `{ kind: 'due', cadence }`, `{ kind:
146	// 'elapsed', ms, text }`, or null for a task with no cadence term (asked at every
147	// tick while it states any condition, it runs whenever those hold). The first
148	// cadence term wins.
149	export function cadenceOf(preconditions) {
150	  for (const ref of entriesOf(preconditions).flat()) {
151	    if (ref.name === DUE_TERM && CADENCES.includes(ref.arg)) return { kind: 'due', cadence: ref.arg };
