17	//
18	// RELEVANCE FIRST (engine/checks/README.md): gated on a task declaration file
19	// existing, so the check is inert on any repo without tasks. Static text over the
20	// self-contained file — a `task.json` parsed whole — keyed off the canonical enum
21	// lists so the legal values never drift from the runtime validator.
22	
23	// The term names the task's own `preconditions.mjs` exports, read as text: the
24	// check runs over a file listing, not a module graph, so it recognises a
25	// task-local condition by the key that defines it. A term the file computes
26	// rather than spells is not found, and its declaration reads as unknown — which
27	// is the same "write it so a reader can see it" the literal rule above states.
28	// Read as TEXT, never imported: a check must not execute a member's own module. So
29	// each term is its name plus the one property of it a declaration can be wrong
30	// about — `needsItem`, which decides whether the term can be judged at a tick at
31	// all. Either quote style, because a member's file is its author's.
32	const TERM_NAME = /^ {2}['"]([^'"]+)['"]:/gm;
33	function siblingTerms(ctx, taskFile) {
34	  const text = ctx.read(taskFile.replace(/task\.json$/, 'preconditions.mjs'));
35	  if (text === null) return new Map();
36	  const body = stripComments(text);
37	  const start = body.indexOf('export const terms');
38	  if (start === -1) return new Map();
39	  const section = body.slice(start);
40	  const named = [...section.matchAll(TERM_NAME)];
41	  return termsMap(Object.fromEntries(named.map((m, i) => {
42	    const block = section.slice(m.index, named[i + 1]?.index ?? section.length);
43	    return [m[1], { signals: [], needsItem: /\bneedsItem\s*:\s*true\b/.test(block) }];
44	  })));
45	}
46	
47	const rule = {
48	  id: 'task-declaration-shape',
49	  severity: 'blocking',
50	  description: 'A tasks/<name>/task.json carries the task contract (id, description, preconditions, expected_outcome) with legal enum values and a well-formed precondition expression stating when the task runs; an agentic task names its worker file and bounds its run, and any code_work carries a timeout and stays task-local',
51	  doc: 'packs/claudinite-tasks/README.md',
52	  why: 'the scheduler run and executor read agent_model/expected_outcome/preconditions from this file, not the work item — an illegal or missing value means a task never fires, fires wrong, or writes past its ceiling',
53	
54	  run(ctx) {
55	    const out = [];
56	    for (const file of ctx.files.filter((f) => TASK_DECLARATION_PATH_RE.test(f))) {
57	      const text = ctx.read(file);
58	      if (text === null) continue;
59	      const flag = (what, fix) => out.push(finding(rule, { file, what, fix }));
60	      const advise = (what, fix) => out.push(finding(rule, { file, severity: 'advisory', what, fix }));
61	
62	      const decl = readDeclarationFields(text);
63	      if (decl.error) {
64	        flag(`is not a JSON object: ${decl.error}`, 'write one JSON object: { "id", "description", "preconditions", "expected_outcome", … }');
65	        continue;
66	      }
67	      const str = (key) => (typeof decl.scalar(key) === 'string' ? decl.scalar(key) : null);
68	      const hasNum = (...keys) => keys.some((key) => typeof decl.scalar(key) === 'number');
69	
