98	// @legacy-tolerance advisory:none retire:#1642
99	export const LEGACY_READY = 'task:ready';
100	// @legacy-tolerance advisory:none retire:#1642
101	export const LEGACY_EXECUTING = 'task:executing';
102	// @legacy-tolerance advisory:none retire:#1642
103	export const LEGACY_AGENT = 'task:agent';
104	
105	// @deprecated The bare park of the two-label era. A park is ONE label now
106	// (`task:status:needs-human-<kind>`); this is still read — on its own it decodes to
107	// `failure`, the conservative lane — and still ensured, because an open item filed
108	// by a fielded engine wears it.
109	export const NEEDS_HUMAN = 'needs-human';
110	
111	// @deprecated Nothing writes this since the approval park: a run that left an
112	// unmerged PR no longer CLOSES as delivered, it parks at the approval lane and
113	// waits to be merged. Kept exported, kept in `QUEUE_LABELS`, and still read
114	// everywhere it was read — closed issues carrying it are stored data, and a decoder
